  CONSTRAINT "LEGACY_ORDER_pkey" PRIMARY KEY ("OrderNo"),
  CONSTRAINT "LEGACY_ORDER_acct_fkey" FOREIGN KEY (acct) REFERENCES accounts (id)
);

CREATE TABLE groups_friends (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  from_group_id INTEGER NOT NULL,
  to_group_id INTEGER NOT NULL,
  CONSTRAINT groups_friends_from_group_id_fkey FOREIGN KEY (from_group_id) REFERENCES "groups" (id) ON DELETE CASCADE,
